if(k==='normalangle'||k==='fluxnormal')b=text(55,45,k==='normalangle'?'The normal is perpendicular to the coil plane':'Flux uses the normal-to-field angle')+line(170,380,450,100)+arrow(310,240,590,240,'#0b8774')+arrow(310,240,460,390,'#2a6bb2')+text(480,215,'B →')+text(470,410,'normal n')+text(160,370,'coil plane')+text(425,285,'θ = 45°')+text(55,455,k==='normalangle'?'τ = NBIA sinθ; plane angle ψ = 90° − θ.':'Φ = BA cosθ; the plane angle would use sinψ.');
