if(k==='splitring')b=text(55,45,'Split-ring commutator: end-view contact model')+'<path d="M360 145 A90 90 0 0 0 360 325" fill="none" stroke="#c87518" stroke-width="18"/>'+'<path d="M380 145 A90 90 0 0 1 380 325" fill="none" stroke="#2a6bb2" stroke-width="18"/>'+box(230,220,45,30)+box(465,220,45,30)+line(305,205,305,100)+line(435,205,435,100)+text(160,80,'coil end A')+text(440,80,'coil end B')+text(85,280,'fixed brush')+text(490,280,'fixed brush')+text(270,375,'insulated gaps at top and bottom')+text(55,425,'The two half-rings rotate together with the coil.')+text(55,465,'Each half-turn swaps brush contact to the physical coil leads.');
if(k==='sliprings')b=text(55,45,'Slip rings: two continuous rings, side-by-side along shaft')+circle(285,240,75)+circle(470,240,75)+line(285,165,285,105)+line(470,165,470,105)+box(180,225,35,30)+box(540,225,35,30)+text(160,85,'coil end A')+text(445,85,'coil end B')+text(75,330,'stationary brush A')+text(460,330,'stationary brush B')+text(55,410,'Each complete ring remains connected to its own physical coil lead.')+text(55,455,'Separate insulated rings rotate; the external polarity alternates.');
if(k==='rotationpositions'||k==='rotorangles')b=text(55,45,'One-turn angle sequence: θ is normal angle to B')+[0,90,180,270].map((a,i)=>{let x=120+i*165;return circle(x,200,40)+arrow(x,200,x+55*Math.cos(a*Math.PI/180),200+55*Math.sin(a*Math.PI/180),'#2a6bb2')+text(x,305,a+'°','#18374d','middle')}).join('')+text(55,375,k==='rotationpositions'?'Torque magnitude: 0, maximum, 0, maximum.':'Flux: +maximum, 0, −maximum, 0.')+text(55,425,k==='rotationpositions'?'Split-ring switching keeps drive torque in the same rotational sense.':'Emf magnitude: 0, maximum, 0, maximum.')+text(55,465,'B is fixed rightward; arrows show the coil normal direction.');
if(k==='torqueripple')b=text(55,45,'Ideal split-ring driving torque versus rotor angle')+axes('positive drive torque','rotor angle')+curve(Array.from({length:121},(_,i)=>[110+i*4.5,340-220*Math.abs(Math.sin(i/120*2*Math.PI))]))+text(90,380,'0°')+text(345,380,'180°')+text(595,380,'360°')+text(55,455,'Simple model: |sinθ| torque; inertia bridges dead points.');
